  async getLedgerIxs(
    userWallet: TransactionSigner,
    inTokenAccount: Address,
    outTokenAccount: Address,
    maxInputAmountChange: BN,
    minOutputAmountChange: BN,
  ): Promise<{ preIx: Instruction; postIx: Instruction }> {
    const assertSwapBalancesIxs = await this.limoClient.assertUserSwapBalancesIxs({
      user: userWallet,
      inputTa: inTokenAccount,
      outputTa: outTokenAccount,
      maxInputAmountChange,
      minOutputAmountChange,
    });

    return { preIx: assertSwapBalancesIxs.beforeSwapIx, postIx: assertSwapBalancesIxs.afterSwapIx };
  }

  async getJupiterPriceWithFallback(getJupiterPriceParams: GetJupiterPriceParams): Promise<GetJupiterPriceResponse> {
    try {
      const jupiterPriceResponse = await fetchJupiterPrice(getJupiterPriceParams);

      return jupiterPriceResponse;
    } catch (error) {
      // Fallback to KSWAP API endpoint
      const endpointUrl = '/jupiter/price';
      try {
        const response = await this._apiClient.get(endpointUrl, { params: getJupiterPriceParams });

        const jupiterPriceResponse = response.data as GetJupiterPriceResponse;

        return jupiterPriceResponse;
      } catch (error) {
        this.logger.error('Error fetching Jupiter price', error);
        throw new Error('Failed to fetch prices from both Jupiter and Birdeye APIs');
      }
    }
  }

